package com.wayfarers.generated.model;

import com.wayfarers.client.WayfarerModelRenderer;
import com.wayfarers.registry.ModEntities;
import net.minecraftforge.client.event.EntityRenderersEvent;

/** Generated by tools/gen_models.py: model layers and renderers of every custom-model creature. */
public final class ModelRegistry {
    private ModelRegistry() {}

    public static void registerLayers(EntityRenderersEvent.RegisterLayerDefinitions event) {
        event.registerLayerDefinition(DrownedWardenModel.LAYER, DrownedWardenModel::createBodyLayer);
    }

    public static void registerRenderers(EntityRenderersEvent.RegisterRenderers event) {
        event.registerEntityRenderer(ModEntities.DROWNED_WARDEN.get(), ctx -> new WayfarerModelRenderer<>(ctx,
                new DrownedWardenModel(ctx.bakeLayer(DrownedWardenModel.LAYER)), 1.4F, "drowned_warden", true));
    }
}
